INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40511, 'Job 5:18', 'Job', 5, 18, 'کۀ هغه زخمى کول کوى، نو هغه يې مرهم پټۍ هم کوى، کۀ هغه وهل کوى، نو د هغۀ لاسونه يې علاج هم کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_18.mp3', '', 1761754199, 1761754199),
(40512, 'Job 5:19', 'Job', 5, 19, 'هغه به تاسو د شپږو افتونو نه بچ کوى، او په اوؤم کښې به تاسو ته هيڅ نقصان نۀ رسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_19.mp3', '', 1761754199, 1761754199),
(40513, 'Job 5:20', 'Job', 5, 20, 'په قحط کښې به هغه تاسو د مرګ نه په بيعه واخلى، او په جنګ کښې به مو د مرګ نه بچ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_20.mp3', '', 1761754199, 1761754199),
(40514, 'Job 5:21', 'Job', 5, 21, 'تاسو به د سپکو خبرو نه بچ شئ، او چې کله تباهى راځى نو تاسو به نۀ يرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_21.mp3', '', 1761754199, 1761754199),
(40515, 'Job 5:22', 'Job', 5, 22, 'په تباهۍ او قحط پورې به تاسو خندا کوئ، او د زمکې د ځنګلى ځناورو نه به نۀ يرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_22.mp3', '', 1761754199, 1761754199),
(40516, 'Job 5:23', 'Job', 5, 23, 'تاسو چې کوم پټى کَرئ نو په هغې کښې به کاڼى نۀ وى، او ځنګلى ځناور به په تاسو حمله نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_23.mp3', '', 1761754199, 1761754199),
(40517, 'Job 5:24', 'Job', 5, 24, 'تاسو ته به پته ولګى چې ستاسو کور محفوظ دے، تاسو به وګورئ چې ستاسو د رَمو نه به هيڅ ورک نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_24.mp3', '', 1761754199, 1761754199),
(40518, 'Job 5:25', 'Job', 5, 25, 'تاسو ته به پته ولګى چې ستاسو اولاد به ډېر وى، داسې بې‌شمېره لکه په زمکه چې واښۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_25.mp3', '', 1761754199, 1761754199),
(40519, 'Job 5:26', 'Job', 5, 26, 'تاسو به خپل قبر ته په بوډاتوب کښې ځئ، لکه چې د فصل ګېډۍ درمند ته په خپل موسم کښې راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_26.mp3', '', 1761754199, 1761754199),
(40520, 'Job 5:27', 'Job', 5, 27, 'ګوره، زمونږه چې د عمر په حقله کومه تجربه ده، دا حقيقت دے. دا نصيحت واوره او په دې باندې عمل وکړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_27.mp3', '', 1761754199, 1761754199),
(40521, 'Deuteronomy 8:1', 'Deuteronomy', 8, 1, 'په وفادارۍ سره د هغو ټولو قوانینو څخه پیروي وکړئ چې نن یې تاسو ته درکوم ترڅو ژوند وکړئ، شمېر مو زیات شي او هغې خاورې ته چې د هغې وعده څښتن ستاسو د نیکونو سره کړې ده، ورننوځئ او هغه ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_1.mp3', '', 1761754199, 1761754199),
(40522, 'Deuteronomy 8:2', 'Deuteronomy', 8, 2, 'در په یاد کړئ چې په تېرو څلوېښتو کلونو کې ستاسو څښتن خدای څنګه تاسو ته په دښته کې په دې اوږده سفر کې لارښوونه وکړه. په تاسو باندې یې سختۍ راوستلې چې ومو ازمایي، ترڅو هغه پوه شي چې ستاسو په زړونو کې څه دي او د هغه په حکمونو باندې عمل کوئ یا نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_2.mp3', '', 1761754199, 1761754199),
(40523, 'Deuteronomy 8:3', 'Deuteronomy', 8, 3, 'هغه په تاسو باندې لوږه راوستله او بیا یې د خوراک دپاره من درکړ، یعنې هغه خواړه چې تاسو او ستاسو نیکونو مخکې هېڅکله خوړلي نه وو. هغه د دې دپاره دا کار وکړ چې تاسو ته دا خبره درزده کړي چې انسان یوازې په ډوډۍ نه بلکې په هره خبره باندې ژوندی دی چې د څښتن د خولې څخه راوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_3.mp3', '', 1761754199, 1761754199),
(40524, 'Deuteronomy 8:4', 'Deuteronomy', 8, 4, 'د دغو څلوېښتو کلونو په دوران کې ستاسو کالي نه دي زاړه شوي او نه مو پښې پړسېدلې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_4.mp3', '', 1761754199, 1761754199),
(40525, 'Deuteronomy 8:5', 'Deuteronomy', 8, 5, 'په یاد لرئ چې ستاسو څښتن خدای تاسو اصلاح کوي او داسې سزا درکوي لکه څنګه چې یو پلار خپل اولادونه اصلاح کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_5.mp3', '', 1761754199, 1761754199),
(40526, 'Deuteronomy 8:6', 'Deuteronomy', 8, 6, 'نو بیا هغه کار کوئ چې څښتن یې درباندې امر کړی دی، یعنې د هغه د قوانینو سره سم ژوند کوئ او د هغه څخه وېرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_6.mp3', '', 1761754199, 1761754199),
(40527, 'Deuteronomy 8:7', 'Deuteronomy', 8, 7, 'ستاسو څښتن خدای تاسو یوې حاصلخېزې ځمکې یعنې داسې ځمکې ته راولي چې سیندونه او چینې لري او د ځمکې لاندې داسې ویالې لري چې اوبه یې درو او غونډیو ته راوځي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_7.mp3', '', 1761754199, 1761754199),
(40528, 'Deuteronomy 8:8', 'Deuteronomy', 8, 8, 'یوه داسې ځمکه چې غنم او اوربشې، انګور، انځر، انار، زیتون او شات په کې پیدا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_8.mp3', '', 1761754199, 1761754199),
(40529, 'Deuteronomy 8:9', 'Deuteronomy', 8, 9, 'دا داسې وطن دی چې خواړه په کې پرېمانه دي او د هېڅ شي کمی په کې نشته. د دې ځای تیږې د اوسپنې څخه ډکې دي او د غونډیو څخه یې مس راویستلی شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_9.mp3', '', 1761754199, 1761754199),
(40530, 'Deuteronomy 8:10', 'Deuteronomy', 8, 10, 'هرڅه چې تاسو غواړئ وخورئ هغه به درورسیږي او تاسو به د هغې حاصلخېزې ځمکې دپاره چې ستاسو څښتن خدای درکړې ده د هغه شکر ادا کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_10.mp3', '', 1761754199, 1761754199),
(40531, 'Deuteronomy 8:11', 'Deuteronomy', 8, 11, 'پام کوئ چې تاسو به هېڅکله خپل څښتن خدای نه هېروئ. هېڅکله د هغه د هغو قوانینو څخه سرغړونه ونه کړئ چې نن یې تاسو ته درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_11.mp3', '', 1761754199, 1761754199),
(40532, 'Deuteronomy 8:12', 'Deuteronomy', 8, 12, 'کله چې تاسو ته د خوراک دپاره هرڅه درورسیږي او د اوسېدلو دپاره ښه ښه کورونه ودان کړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_12.mp3', '', 1761754199, 1761754199),
(40533, 'Deuteronomy 8:13', 'Deuteronomy', 8, 13, 'او کله چې ستاسو پادې او رمې، ستاسو سپین زر او سره زر او نور ټول شیان زیات شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_13.mp3', '', 1761754199, 1761754199),
(40534, 'Deuteronomy 8:14', 'Deuteronomy', 8, 14, 'نو پام کوئ چې تاسو به نه مغروره کېږئ او خپل څښتن خدای به چې تاسو یې د مصر د غلامۍ څخه ازاد کړئ، نه هېروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_14.mp3', '', 1761754199, 1761754199),
(40535, 'Deuteronomy 8:15', 'Deuteronomy', 8, 15, 'هغه د هغې پراخې او وېروونکې دښتې په لاره تاسو بوتلئ چې زهرجن ماران او لړمان په کې وو. هغه په هغې وچې او بې اوبو ځمکه کې د کلک ګټ څخه ستاسو دپاره اوبه راوویستلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_15.mp3', '', 1761754199, 1761754199),
(40536, 'Deuteronomy 8:16', 'Deuteronomy', 8, 16, 'هغه په دښته کې تاسو ته د خوراک دپاره من درکړ چې داسې خواړه وو چې ستاسو نیکونو هېڅکله خوړلي نه وو. له دې امله هغه په تاسو باندې سختۍ راوستلې چې تاسو وازمایي، ترڅو په اخر کې هغه تاسو ته د ښو ښو شیانو سره برکت درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_16.mp3', '', 1761754199, 1761754199),
(40537, 'Deuteronomy 8:17', 'Deuteronomy', 8, 17, 'نو بیا باید هېڅکله داسې فکر ونه کړئ چې تاسو په خپل قدرت او قوت سره خپل ځانونه شتمن کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_17.mp3', '', 1761754199, 1761754199),
(40538, 'Deuteronomy 8:18', 'Deuteronomy', 8, 18, 'په یاد ولرئ چې دا ستاسو څښتن خدای دی چې تاسو ته دا توان درکوي چې شتمن شئ. څښتن ځکه دا کار کوي چې هغه نن هم هغه لوظ ته وفادار پاتې دی چې ستاسو د نیکونو سره یې کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy8_verse_18.mp3', '', 1761754199, 1761754199),
(40539, 'Hosea 9:1', 'Hosea', 9, 1, 'ای د اسراییلو خلکو، د نورو قومونو د اخترونو د لمانځلو نه لاس واخلئ، ځکه چې تاسو خپل خدای پریښی دی او د هغه سره مو بې‌وفایي کړې ده. تاسو بتانو ته په عبادت کولو سره په ټولو ځایونو خپل ځانونه لکه د فاحشو په شان خرڅ کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_1.mp3', '', 1761754199, 1761754199),
(40540, 'Hosea 9:2', 'Hosea', 9, 2, 'خو اوس به نور تاسو سره په پوره اندازه غلې دانې او شراب نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_2.mp3', '', 1761754199, 1761754199),
(40541, 'Hosea 9:3', 'Hosea', 9, 3, 'د اسراییلو خلک به نور د څښتن په وطن کې پاتې نه شي، بلکې هغوی باید بېرته مصر ته لاړ شي او په آشور کې به حرام خواړه خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_3.mp3', '', 1761754199, 1761754199),
(40542, 'Hosea 9:4', 'Hosea', 9, 4, 'هلته به هغوی د دې توان نه لري چې څښتن ته د نذرانې په توګه شراب توی کړي او د هغوی په قربانیو باندې به څښتن خوشحاله نه شي. هرڅوک چې د هغوی خواړه وخوري، هغوی به داسې ناپاکه شي لکه څوک چې د مړي د جنازې په مراسمو کې خواړه خوري. په دې باندې به یوازې د هغوی لوږه له منځه ځي. خو هغه خواړه باید د څښتن عبادتځای ته رانه وړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_4.mp3', '', 1761754199, 1761754199),
(40543, 'Hosea 9:5', 'Hosea', 9, 5, 'نو تاسو به د اختر په ورځو کې څه کوئ او څنګه به د څښتن اخترونه لمانځئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_5.mp3', '', 1761754199, 1761754199),
(40544, 'Hosea 9:6', 'Hosea', 9, 6, 'ګورئ، که څه هم هغوی به د تباهۍ څخه وتښتي، خو مصریان به هغوی سره راټول کړي او د ممفیس په ښار کې به یې ښخ کړي! په هغو ځایونو کې چې د هغوی د سپینو زرو خزانې او یو وخت په کې د هغوی کورونه وو، په هغو کې به هرزه بوټي او د اغزیو بوټي راشنه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_6.mp3', '', 1761754199, 1761754199),
(40545, 'Hosea 9:7', 'Hosea', 9, 7, 'اسراییلو ته د سزا ورکولو او د حساب کولو ورځ رارسېدلې ده. کله چې دا کار وشي، نو اسراییل به ورباندې پوه شي. تاسو وایئ چې دا پیغمبر کم‌عقل دی او دا د الهام رسوونکی سړی لېونی دی. تاسو داسې وایئ، ځکه چې ستاسو ګناهونه ډېر زیات دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_7.mp3', '', 1761754199, 1761754199),
(40546, 'Hosea 9:8', 'Hosea', 9, 8, 'پیغمبر د خدای له خوا د اسراییلو پهره‌دار دی. خو زه چې هر‌چېرته ځم، نو تاسو کوښښ کوئ چې د مرغۍ په شان مې په دام کې راګېر کړئ. حتی تر دې پورې چې د خدای په کور کې هم خلک د پیغمبر دښمنان شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_8.mp3', '', 1761754199, 1761754199),
(40547, 'Hosea 9:9', 'Hosea', 9, 9, 'هغوی په خپلو کارونو کې داسې فاسد شوي دي، لکه څنګه چې د جبعې په ښار کې وو. خدای به د هغوی ګناهونه رایاد کړي او د هغو په خاطر به ورته سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_9.mp3', '', 1761754199, 1761754199),
(40548, 'Hosea 9:10', 'Hosea', 9, 10, 'څښتن وایي: «کله چې ما د لومړي ځل دپاره اسراییل ولیدل، نو هغه داسې وو لکه په دښته کې چې انګور پیدا شي. کله چې ما د لومړي ځل دپاره ستاسو نیکونه ولیدل، هغه داسې وو لکه د موسم لومړني پاخه شوي انځران مې چې لیدلي وي. خو کله چې هغوی د فغور غره ته راغلل، نو هغوی خپل ځانونه د بعل شرمناک بت ته وقف کړل او ډېر زر د بعل د بت په شان چې هغوی ورسره مینه کوله، د کرکې وړ وګرځېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_10.mp3', '', 1761754199, 1761754199),
(40549, 'Hosea 9:11', 'Hosea', 9, 11, 'د اسراییلو شان او شوکت به لکه د مرغۍ په شان والوځي او د هغوی به نور اولادونه نه پیدا کیږي، د هغوی ښځې به نورې نه امیدوارې کیږي او نه به یې اولاد په خېټه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_11.mp3', '', 1761754199, 1761754199),
(40550, 'Hosea 9:12', 'Hosea', 9, 12, 'خو که د هغوی اولادونه هم پیدا شي، نو زه به یې ورڅخه واخلم او یو به یې هم ژوندی پرېنږدم. کله چې زه دا خلک پرېږدم، نو هغوی به د ډېرو وېروونکو پېښو سره مخ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_12.mp3', '', 1761754199, 1761754199),
(40551, 'Hosea 9:13', 'Hosea', 9, 13, 'ما لیدلي دي چې اسراییل لکه د خرما د نیالګیو په شان په ښه ځای کې کرل شوي دي، خو هغوی باید خپل زامن جنګ ته ولېږي چې ووژل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_13.mp3', '', 1761754199, 1761754199),
(40552, 'Hosea 9:14', 'Hosea', 9, 14, 'ای څښتنه، زه به ستا نه د دې خلکو دپاره د څه شي سوال وکړم؟ د هغوی ښځې شنډې کړه چې ماشومان ونه زېږوي او د هغوی په سینو کې شیدې وچې کړه چې ونه شي کولای خپل ماشومان وروزي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_14.mp3', '', 1761754199, 1761754199),
(40553, 'Hosea 9:15', 'Hosea', 9, 15, 'څښتن وایي: «د هغوی ټوله بدکاري د جلجال په ښار کې پیل شوه. په هماغه ځای کې ما د هغوی څخه کرکه پیل کړه. د همدې بدو عملونو په خاطر به زه هغوی د خپل وطن نه وشړم. زه به نور د هغوی سره مینه نه کوم. د هغوی ټولو مشرانو زما په وړاندې سرکښي کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_15.mp3', '', 1761754199, 1761754199),
(40554, 'Hosea 9:16', 'Hosea', 9, 16, 'د اسراییلو خلک د هغه بوټي په شان دي چې ریښې یې وچې شوې وي او مېوه نه نیسي. د هغوی به اولادونه نه پیدا کیږي، خو که پیدا هم شي، زه به د ‎هغوی ګران اولادونه ووژنم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_16.mp3', '', 1761754199, 1761754199),
(40555, 'Hosea 9:17', 'Hosea', 9, 17, 'زما خدای به هغوی پرېږدي، ځکه چې هغوی د هغه خبرو ته غوږ ونه نیوه. نو هغوی به د نورو قومونو په منځ کې سرګردانه ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea9_verse_17.mp3', '', 1761754199, 1761754199),
(40556, 'Leviticus 19:1', 'Leviticus', 19, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_1.mp3', '', 1761754199, 1761754199),
(40557, 'Leviticus 19:2', 'Leviticus', 19, 2, '«د اسراییلو د ټول قوم سره خبرې وکړه او ورته ووایه: سپېڅلي اوسئ، ځکه چې زه ستاسو څښتن خدای سپېڅلی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_2.mp3', '', 1761754199, 1761754199),
(40558, 'Leviticus 19:3', 'Leviticus', 19, 3, 'تاسو هر یو باید د خپل مور او پلار درناوی وکړئ او باید د سبت د ورځې څخه پیروي وکړئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_3.mp3', '', 1761754199, 1761754199),
(40559, 'Leviticus 19:4', 'Leviticus', 19, 4, 'ما مه پرېږدئ او د بتانو عبادت مه کوئ. د فلزاتو څخه خدایان مه جوړوئ او عبادت یې مه کوئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_4.mp3', '', 1761754199, 1761754199),
(40560, 'Leviticus 19:5', 'Leviticus', 19, 5, 'کله چې تاسو د سلامتۍ د نذرانې دپاره څښتن ته یو حیوان قرباني کوئ، هغه په یوې داسې طریقې سره قرباني کړئ چې زما له خوا قبوله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_5.mp3', '', 1761754199, 1761754199),
(40561, 'Leviticus 19:6', 'Leviticus', 19, 6, 'غوښه باید په هماغه ورځ چې قرباني کوئ وخورئ یا په راتلونکې ورځ. هرڅه چې تر درېمې ورځې پورې پاتې شي، باید وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_6.mp3', '', 1761754199, 1761754199),
(40562, 'Leviticus 19:7', 'Leviticus', 19, 7, 'که چېرې د هغې څخه لږه په درېمه ورځ وخوړل شي، هغه ناپاکه ده او دا نذرانه به قبوله نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_7.mp3', '', 1761754199, 1761754199),
(40563, 'Leviticus 19:8', 'Leviticus', 19, 8, 'هرڅوک چې هغه وخوري، هغه به ګناهکار وي، ځکه چې هغه څه چې څښتن ته سپېڅلي دي، هغه یې عادي ګڼلي دي. هغه کس باید د خدای د قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_8.mp3', '', 1761754199, 1761754199),
(40564, 'Leviticus 19:9', 'Leviticus', 19, 9, 'کله چې تاسو د خپلې ځمکې حاصلات لو کوئ، نو هغه د پټي تر غاړو پورې مه لو کوئ او هغه وږي چې د لو څخه پاتې شوي وي، هغه مه راټولوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_9.mp3', '', 1761754199, 1761754199),
(40565, 'Leviticus 19:10', 'Leviticus', 19, 10, 'خپل د انګورو باغ ته دوهم ځل مه ورځئ او هغه انګور مه راټولوئ چې رالوېدلي وي. هغه غریبانو او پردیو خلکو ته پرېږدئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_10.mp3', '', 1761754199, 1761754199),
(40566, 'Leviticus 19:11', 'Leviticus', 19, 11, 'غلا مه کوئ. یو بل ته دروغ مه وایئ او یو بل مه غولوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_11.mp3', '', 1761754199, 1761754199),
(40567, 'Leviticus 19:12', 'Leviticus', 19, 12, 'زما په نوم په دروغو قسم مه خورئ او په دې ډول د خپل خدای نوم مه سپکوئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_12.mp3', '', 1761754199, 1761754199),
(40568, 'Leviticus 19:13', 'Leviticus', 19, 13, 'خپل ګاونډی مه لوټوئ او هغه مه غولوئ. د یو مزدور اجوره حتی د یوې شپې دپاره هم مه ځنډوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_13.mp3', '', 1761754199, 1761754199),
(40569, 'Leviticus 19:14', 'Leviticus', 19, 14, 'کڼو خلکو ته ښکنځلې مه کوئ او د ړندو په مخکې داسې شی مه ږدئ چې هغوی ورباندې وښوییږي، زما څخه ووېرېږئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_14.mp3', '', 1761754199, 1761754199),
(40570, 'Leviticus 19:15', 'Leviticus', 19, 15, 'عدالت تر پښو مه لاندې کوئ. د غریب طرفداري مه کوئ او د لویانو خاطر مه کوئ، خو د نورو سره په انصاف قضاوت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_15.mp3', '', 1761754199, 1761754199),
(40571, 'Leviticus 19:16', 'Leviticus', 19, 16, 'د هېچا په اړه دروغ مه خپروئ او کله چې یو کس په محکمه کې په مرګ باندې محکوم وي، نو ښکاره خبرې وکړئ، کېدای شي چې ستاسو شاهدي د هغه سره مرسته وکړي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_16.mp3', '', 1761754199, 1761754199),
(40572, 'Leviticus 19:17', 'Leviticus', 19, 17, 'د خپل ورور سره په خپل زړه کې کینه مه ساتئ. هغه په ښکاره د خپلې ګناه په خاطر ورټئ، ترڅو د هغه په ګناه کې شریک نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_17.mp3', '', 1761754199, 1761754199),
(40573, 'Leviticus 19:18', 'Leviticus', 19, 18, 'د خپلو خلکو څخه د بدل اخیستلو پسې مه ګرځئ. د هغوی څخه کرکه مه کوئ، خو د خپل ګاونډي سره د خپل ځان په شان مینه کوئ. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_18.mp3', '', 1761754199, 1761754199),
(40574, 'Leviticus 19:19', 'Leviticus', 19, 19, 'زما د فرمانونو څخه پیروي وکړئ. غیر همجنس کورني حیوانات د نسل د پیدا کولو دپاره سره مه یوځای کوئ. په خپل پټي کې دوه ډوله تخمونه مه کرئ. داسې کالي مه اغوندئ چې د دوو مختلفو جنسونو څخه جوړ شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_19.mp3', '', 1761754199, 1761754199),
(40575, 'Leviticus 19:20', 'Leviticus', 19, 20, 'که چېرې یو کس د یوې داسې وینځې سره چې هغه د بل کس سره کوژدن شوې وي زنا وکړي، که څه هم هغه بل کس د هغې د ازادېدلو په خاطر پیسې نه وي ورکړې، نو باید هغې وینځې او هغه کس ته چې د هغې سره یې زنا کړې وه، سزا ورکړل شي. خو هغوی دې ونه وژل شي، ځکه چې هغه ازاده شوې نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_20.mp3', '', 1761754199, 1761754199),
(40576, 'Leviticus 19:21', 'Leviticus', 19, 21, 'هغه سړی به د تاوان د نذرانې په توګه یو پسه د سپېڅلې خېمې د دروازې په خوله کې څښتن ته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_21.mp3', '', 1761754199, 1761754199),
(40577, 'Leviticus 19:22', 'Leviticus', 19, 22, 'په هغه باندې به کاهن د څښتن په حضور کې د هغه د ګناه په خاطر کفاره ادا کړي او د هغه ګناه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_22.mp3', '', 1761754199, 1761754199),
(40578, 'Leviticus 19:23', 'Leviticus', 19, 23, 'کله چې تاسو د کنعان خاورې ته ورننوځئ او د مېوې یوه ونه وکرئ، هغه مېوه د لومړنیو درېو کلونو دپاره حرامه وګڼئ. په دې موده کې تاسو باید هغه مېوه ونه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_23.mp3', '', 1761754199, 1761754199),
(40579, 'Leviticus 19:24', 'Leviticus', 19, 24, 'په څلورم کال به هغه ټوله مېوه ما یعنې څښتن ته د شکرګزارۍ په خاطر وقف شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_24.mp3', '', 1761754199, 1761754199),
(40580, 'Leviticus 19:25', 'Leviticus', 19, 25, 'خو په پنځم کال به هغه مېوه تاسو ته حلاله وي. که چېرې تاسو دا ټول کارونه وکړئ، ستاسو ونې به زیاته مېوه ونیسي. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_25.mp3', '', 1761754199, 1761754199),
(40581, 'Leviticus 19:26', 'Leviticus', 19, 26, 'داسې غوښه مه خورئ چې وینه په کې وي. فال مه ګورئ او کوډې مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_26.mp3', '', 1761754199, 1761754199),
(40582, 'Leviticus 19:27', 'Leviticus', 19, 27, 'د خپلو شقیقو ویښتان مه خرایئ او ږیره مه لنډوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_27.mp3', '', 1761754199, 1761754199),
(40583, 'Leviticus 19:28', 'Leviticus', 19, 28, 'د مړي په غم کې خپل بدنونه مه غوڅوئ او خالونه ورباندې مه جوړوئ. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_28.mp3', '', 1761754199, 1761754199),
(40584, 'Leviticus 19:29', 'Leviticus', 19, 29, 'د خپلو لورګانو څخه بدلمنې مه جوړوئ او هغوی مه شرموئ. که داسې وکړئ، نو دا خاوره به په بدلمنۍ بدله شي او د بدکارۍ څخه به ډکه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_29.mp3', '', 1761754199, 1761754199),
(40585, 'Leviticus 19:30', 'Leviticus', 19, 30, 'د سبت د ورځې څخه پیروي وکړئ او د هغه ځای درناوی وکړئ چې زما عبادت په کې کیږي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_30.mp3', '', 1761754199, 1761754199),
(40586, 'Leviticus 19:31', 'Leviticus', 19, 31, 'هغو خلکو ته مه ورځئ چې هغوی دعوه کوي چې دوی کولای شي د مړو سره خبرې وکړي. همدارنګه د فال کتونکو پسې مه ګرځئ، ځکه چې د هغوی په وسیله به تاسو ناپاک شئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_31.mp3', '', 1761754199, 1761754199),
(40587, 'Leviticus 19:32', 'Leviticus', 19, 32, 'د سپین ږیرو په مخکې پاڅېږئ، د مشرانو درناوی کوئ او زما څخه وېرېږئ. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_32.mp3', '', 1761754199, 1761754199),
(40588, 'Leviticus 19:33', 'Leviticus', 19, 33, 'د هغو پردیو خلکو سره بد چلند مه کوئ چې ستاسو په خاوره کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_33.mp3', '', 1761754199, 1761754199),
(40589, 'Leviticus 19:34', 'Leviticus', 19, 34, 'د هغوی سره د یو اسراییلي په شان چلند وکړئ او د خپلو ځانونو په شان ورسره مینه وکړئ. دا یاد ساتئ چې تاسو هم یو وخت د مصر په خاوره کې پردي وئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_34.mp3', '', 1761754199, 1761754199),
(40590, 'Leviticus 19:35', 'Leviticus', 19, 35, 'کله چې تاسو یو شی اندازه کوئ یا هغه وزن کوئ، نو غلطي په کې مه کوئ او هېڅوک مه غولوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_35.mp3', '', 1761754199, 1761754199),
(40591, 'Leviticus 19:36', 'Leviticus', 19, 36, 'د سمو ترازوګانو، سمو وزنونو او سمو اندازو څخه کار اخلئ. زه ستاسو څښتن خدای یم او ما تاسو د مصر څخه راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_36.mp3', '', 1761754199, 1761754199),
(40592, 'Leviticus 19:37', 'Leviticus', 19, 37, 'زما د ټولو فرمانونو او قوانینو څخه پیروي کوئ. زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus19_verse_37.mp3', '', 1761754199, 1761754199),
(40593, 'Exodus 38:1', 'Exodus', 38, 1, 'بزل ییل د اکاسۍ د لرګي څخه یو د قربانۍ ځای جوړ کړ چې یو متر او دېرش سانتي لوړ ؤ. هغه څلور کنجه ؤ، دوه متره او شل سانتي اوږد ؤ او دوه متره او شل سانتي پلن ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_1.mp3', '', 1761754199, 1761754199),
(40594, 'Exodus 38:2', 'Exodus', 38, 2, 'هغه د څلورو کنجونو دپاسه ښکرونه جوړ کړل چې هغه د قربانۍ د خای سره ټول د یوې ټوټې لرګي څخه جوړ شول او ټولو ته یې د برنجو پوښ ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_2.mp3', '', 1761754199, 1761754199),
(40595, 'Exodus 38:3', 'Exodus', 38, 3, 'د هغه ټول سامان یې د برنجو څخه جوړ کړ، یعنې د ایرو د لېرې کولو لوښي او د هغه بېلچې، د وینې د شیندلو کاسې، د غوښې قاشق پنجې او د اور لوښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_3.mp3', '', 1761754199, 1761754199),
(40596, 'Exodus 38:4', 'Exodus', 38, 4, 'هغه یوه د برنجو جالۍ جوړه کړه او د قربانۍ د ځای د څنډې لاندې یې کېښودله، ترڅو د قربانۍ د ځای تر نیمایي پورې ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_4.mp3', '', 1761754199, 1761754199),
(40597, 'Exodus 38:5', 'Exodus', 38, 5, 'د دې دپاره یې د برنجو کړۍ ګانې جوړې کړې چې د جالۍ د څلورو کنجونو میلې ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_5.mp3', '', 1761754199, 1761754199),
(40598, 'Exodus 38:6', 'Exodus', 38, 6, 'د اکاسۍ د لرګي څخه یې د وړلو میلې جوړې کړې او د برنجو پوښ یې ورته ورکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_6.mp3', '', 1761754199, 1761754199),
(40599, 'Exodus 38:7', 'Exodus', 38, 7, 'او د قربانۍ د ځای د دواړو اړخونو په کړیو کې یې ولګولې. د قربانۍ ځای د تختو څخه جوړ شوی ؤ او تش ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_7.mp3', '', 1761754199, 1761754199),
(40600, 'Exodus 38:8', 'Exodus', 38, 8, 'بزل ییل برنجي تشت او د هغه برنجي پایه د هغو ښځو د برنجي آیینو څخه جوړ کړل چې د سپېڅلې خېمې په دروازه کې یې خدمت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_8.mp3', '', 1761754199, 1761754199),
(40601, 'Exodus 38:9', 'Exodus', 38, 9, 'بزل ییل د سپېڅلې خېمې دپاره یوه حوېلۍ جوړه کړه. جنوب خوا یې پنځه څلوېښت متره اوږده وه او د ښه کتان پردې یې درلودلې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_9.mp3', '', 1761754199, 1761754199),
(40602, 'Exodus 38:10', 'Exodus', 38, 10, 'چې د برنجو په شلو پایو کې د شلو برنجي ستنو په وسیله ټینګې شوې وې، چې د سپینو زرو څخه جوړ شوي چنګکونه او سیخونه په کې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_10.mp3', '', 1761754199, 1761754199),
(40603, 'Exodus 38:11', 'Exodus', 38, 11, 'حوېلۍ د شمال خواته هم همداسې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_11.mp3', '', 1761754199, 1761754199),
(40604, 'Exodus 38:12', 'Exodus', 38, 12, 'د حوېلۍ په لوېدیځه خوا کې پردې وې چې دوه ویشت متره اوږدې وې او لس ستنې او پایې یې درلودلې چې د سپینو زرو څخه جوړ شوي چنګکونه او سیخونه ورسره وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_12.mp3', '', 1761754199, 1761754199),
(40605, 'Exodus 38:13', 'Exodus', 38, 13, 'ختیځې خواته یعنې هغه ځای کې چې د ننوتلو دروازه وه، هم حوېلۍ دوه ویشت متره پلنه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_13.mp3', '', 1761754199, 1761754199),
(40606, 'Exodus 38:16', 'Exodus', 38, 16, 'د حوېلۍ ګردچاپېره ټولې پردې د ښه کتان څخه جوړې شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_16.mp3', '', 1761754199, 1761754199),
(40607, 'Exodus 38:17', 'Exodus', 38, 17, 'د ستنو دپاره چې کومې پایې وې، هغه د برنجو څخه جوړې شوې وې او چنګکونه، سیخونه او د ستنو د سرونو پوښونه د سپینو زرو څخه جوړ شوي وو. د حوېلۍ ګردچاپېره ټولې ستنې د سپینو زرو د سیخونو سره نښلول شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_17.mp3', '', 1761754199, 1761754199),
(40608, 'Exodus 38:18', 'Exodus', 38, 18, 'د حوېلۍ د دروازې پرده د ابي، بانجاني او سرو وړیو او د ښه کتان څخه جوړه شوې وه او ګلدوزي شوې وه. هغه نهه متره اوږده او د حوېلۍ د پردو په شان دوه متره او شل سانتي لوړه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_18.mp3', '', 1761754199, 1761754199),
(40609, 'Exodus 38:19', 'Exodus', 38, 19, 'هغه په څلورو داسې ستنو باندې ټینګه شوې وه چې په څلورو برنجي پایو کې وې. چنګکونه، د سرونو پوښونه او سیخونه یې د سپینو زرو څخه جوړ شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_19.mp3', '', 1761754199, 1761754199),
(40610, 'Exodus 38:20', 'Exodus', 38, 20, 'د خېمې او د هغې د ګردچاپېره حوېلۍ ټول موږي برنجي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_20.mp3', '', 1761754199, 1761754199);